using CanDoItAll.Modules.Projects;
using CanDoItAll.Modules.Workbench;

namespace CanDoItAll.Web.Api;

internal static partial class OpenApiContractDescriptions {
    private const string LifecycleOriginal = "Exact original operation address, interpretation and command retained before dispatch. Never replace its expectations during recovery.";
    private const string LifecycleReceipt = "Historical acceptance for the exact original command. It confirms the database mutation, not completion of every cleanup obligation.";
    private const string LifecycleEdge = "Original edge ID and both endpoint lifetimes from the same hierarchy observation. A newly read edge cannot substitute for this expectation.";
    private const string LifecycleDiagnostics = "True when diagnostics could not be recorded. Preserve the reported mutation outcome; logging failure is not proof of rollback.";

