        [typeof(ProjectLifecycleApiResponse.Unavailable)] = new("Original evidence is inaccessible or unsupported; no absence or retry authority is inferred.",
            (nameof(ProjectLifecycleApiResponse.Unavailable.Original), Operation),
            (nameof(ProjectLifecycleApiResponse.Unavailable.Reason), "Why the original evidence cannot be disclosed.")),
