        [typeof(ProjectDeletionCompletionAddress)] = new("Dataset-bound identity of the original deletion completion record.",
            (nameof(ProjectDeletionCompletionAddress.DatabaseProfileId), "Original database profile ID."),
            (nameof(ProjectDeletionCompletionAddress.Namespace), "Original dataset namespace."),
            (nameof(ProjectDeletionCompletionAddress.Id), "Original nonempty completion identity.")),
        [typeof(ProjectDeletionCompletionId)] = new("Nonempty deletion completion identity.",
            (nameof(ProjectDeletionCompletionId.Value), "Completion GUID assigned for the original deletion.")),
        [typeof(ProjectDeletionObligation)] = new("One exact participant cleanup obligation from the original deletion.",
            (nameof(ProjectDeletionObligation.Participant), "Stable participant identity, bounded to 64 UTF-8 bytes."),
            (nameof(ProjectDeletionObligation.RecoveryId), "Nonempty original participant recovery ID.")),
        [typeof(ProjectDeletionRecovery)] = new("Retained deletion failures and original owner-release uncertainty.",
            (nameof(ProjectDeletionRecovery.Failures), "Participant failures requiring exact recovery, with no new deletion implied."),
