        [typeof(ProjectLifecycleContextChange)] = new(EnumText<ProjectLifecycleContextChange>("Original context boundary that changed.")),
        [typeof(ProjectLifecycleRefusal)] = new(EnumText<ProjectLifecycleRefusal>("Definite lifecycle refusal reason.")),
        [typeof(ProjectLifecycleUnavailableReason)] = new(EnumText<ProjectLifecycleUnavailableReason>("Reason lifecycle evidence is unavailable.")),
        [typeof(ProjectLifecycleRecoveryReason)] = new(EnumText<ProjectLifecycleRecoveryReason>("Reason original lifecycle reconciliation is required."))
